void TileSetAtlasSourceEditor::shortcut_input(const Ref<InputEvent> &r_event) {
	// Check for shortcuts.
	if (ED_IS_SHORTCUT("tiles_editor/delete", r_event)) {
		if (tools_button_group->get_pressed_button() == tool_select_button && !selection.is_empty()) {
			_menu_option(TILE_DELETE);
			accept_event();
		}
	}
}
